// WebSocket transport: connects to the server's reserved `/_pathland/ws`,
// applies each received PLPL batch to the DOM renderer, negotiates the protocol
// version, and reports raw-input events back. Reconnect/backoff, heartbeat, and
// sequence-gap recovery (lost batches without a disconnect → META::RESYNC) live
// here.

import type { Batch } from "./plpl";
import { ProtocolError, parseBatch } from "./plpl";
import { applyBatch, type DomRenderer } from "./apply";
import { encodePing, encodeResync } from "./events";
import { FLAG_HOST_TO_GUEST, VERSION } from "./constants";
import { log } from "./log";
import { describeBatch, describeBatchDetail } from "./describe";

export type TransportStatus = "connecting" | "open" | "reconnecting";

export interface TransportOptions {
  /** WebSocket URL, e.g. `ws://host/_pathland/ws`. */
  url: string;
  /** The retained-node registry deltas are applied to. */
  renderer: DomRenderer;
  /** Invoked after a batch is successfully applied. */
  onBatch?: (batch: Batch) => void;
  onStatus?: (status: TransportStatus) => void;
  /**
   * Invoked on every socket open (first connect and reconnect), before any RESYNC —
   * the DOM client sends its `META::ENVIRONMENT` (viewport + route) here as the first
   * message so the server session seeds from it.
   */
  onOpen?: (transport: Transport) => void;
  /** Injectable socket factory (tests). */
  createSocket?: (url: string) => WebSocket;
}

const BASE_DELAY_MS = 500;
const MAX_DELAY_MS = 30000;
const MAX_ATTEMPTS = 30;

// Heartbeat (spec/OPCODE.md §Transport heartbeat): the client probes server
// liveness with META::PING every HEARTBEAT_INTERVAL_MS. It treats the connection
// as dead when NO server batch of any kind (deltas, META::PONG) has arrived for
// HEARTBEAT_TIMEOUT_MS — a stalled-but-"open" socket never fires onclose, so the
// watchdog forces a close to trigger the reconnect flow (which re-sends the
// environment + requests a META::RESYNC). The PING also counts as inbound WS
// traffic, keeping the connection warm through proxies and idle-spin-down.
const HEARTBEAT_INTERVAL_MS = 5000;
const HEARTBEAT_TIMEOUT_MS = 15000;
const WATCHDOG_CHECK_MS = 1000;

// Numeric readyState (the WebSocket global may be absent in test environments).
const WS_OPEN = 1;

export class Transport {
  private ws: WebSocket | null = null;
  private attempt = 0;
  private stopped = false;
  private readonly options: TransportOptions;
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private watchdogTimer: ReturnType<typeof setInterval> | null = null;
  private lastActivityAt = 0;
  /**
   * The sequence the next guest → host delta batch must carry, or `null` before
   * the first batch / after a gap or reconnect (re-baseline on the next batch).
   * See spec/OPCODE.md §Sequence gap detection.
   */
  private expectedSequence: number | null = null;

  constructor(options: TransportOptions) {
    this.options = options;
  }

  /** Connect and stay connected (auto-reconnect with exponential backoff). */
  start(): void {
    this.stopped = false;
    this.lastActivityAt = Date.now();
    this.startHeartbeat();
    this.connect();
  }

  /** Permanently close the socket and cancel reconnects. */
  stop(): void {
    this.stopped = true;
    this.stopHeartbeat();
    if (this.ws) {
      this.ws.onclose = null;
      this.ws.close();
      this.ws = null;
    }
  }

  get open(): boolean {
    return this.ws !== null && this.ws.readyState === WS_OPEN;
  }

  send(bytes: Uint8Array): void {
    if (!this.open) {
      return;
    }
    // Best-effort description (never drops the bytes, even if undecodable).
    try {
      const batch = parseBatch(bytes);
      log.info("ws", "→ send", describeBatch(batch));
      log.debug("ws", "→ send detail", describeBatchDetail(batch));
    } catch {
      log.info("ws", "→ send", bytes.length, "bytes");
    }
    this.ws!.send(bytes);
  }

  /** Start the META::PING sender + the no-activity watchdog (one-shot, survives reconnects). */
  private startHeartbeat(): void {
    if (this.pingTimer || this.watchdogTimer) {
      return;
    }
    this.pingTimer = setInterval(() => {
      if (this.open) {
        this.send(encodePing());
      }
    }, HEARTBEAT_INTERVAL_MS);
    this.watchdogTimer = setInterval(() => {
      if (!this.open) {
        return;
      }
      if (Date.now() - this.lastActivityAt > HEARTBEAT_TIMEOUT_MS) {
        log.warn("ws", `no server frame for ${HEARTBEAT_TIMEOUT_MS} ms — reconnecting`);
        this.ws?.close();
      }
    }, WATCHDOG_CHECK_MS);
  }

  private stopHeartbeat(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
    if (this.watchdogTimer) {
      clearInterval(this.watchdogTimer);
      this.watchdogTimer = null;
    }
  }

  private connect(): void {
    log.debug("ws", "connecting", this.options.url);
    const ws = this.options.createSocket
      ? this.options.createSocket(this.options.url)
      : new WebSocket(this.options.url);
    this.ws = ws;
    ws.binaryType = "arraybuffer";
    ws.onopen = () => {
      // A reconnect means the client missed deltas while disconnected: request a
      // full snapshot (META::RESYNC). The first connect never does — the client
      // already has the whole UI from the SSR HTML. On EVERY open (before any
      // resync) the client sends its environment (viewport + route).
      this.lastActivityAt = Date.now();
      // Re-baseline the sequence on the next guest → host batch (a fresh
      // connection's stream restarts; see §Sequence gap detection).
      this.expectedSequence = null;
      const reconnected = this.attempt > 0;
      this.attempt = 0;
      log.info("ws", reconnected ? "connected (reconnect)" : "connected");
      this.options.onStatus?.("open");
      this.options.onOpen?.(this);
      if (reconnected) {
        log.debug("ws", "requesting RESYNC (missed deltas while disconnected)");
        this.send(encodeResync());
      }
    };
    ws.onmessage = (event) => this.handleMessage(event.data);
    ws.onerror = () => {
      log.error("ws", "socket error");
      // onclose always follows; nothing to do here.
    };
    ws.onclose = () => {
      this.ws = null;
      if (this.stopped) {
        log.debug("ws", "closed (stopped)");
        return;
      }
      log.info("ws", "closed — reconnecting (attempt", this.attempt + 1 + ")");
      this.options.onStatus?.("reconnecting");
      this.scheduleReconnect();
    };
  }

  private scheduleReconnect(): void {
    if (this.attempt >= MAX_ATTEMPTS) {
      return;
    }
    const delay = Math.min(BASE_DELAY_MS * 2 ** this.attempt, MAX_DELAY_MS);
    this.attempt++;
    setTimeout(() => this.connect(), delay);
  }

  private handleMessage(data: unknown): void {
    // Any server batch (a delta, a META::PONG, anything) proves the connection
    // is alive — reset the heartbeat watchdog.
    this.lastActivityAt = Date.now();
    let bytes: Uint8Array;
    if (data instanceof ArrayBuffer) {
      bytes = new Uint8Array(data);
    } else if (data instanceof Blob) {
      // A Blob read can abort (socket close / navigation) — swallow it rather than
      // surface an unhandled promise rejection.
      data.arrayBuffer()
        .then((buffer) => this.handleMessage(buffer))
        .catch(() => undefined);
      return;
    } else {
      bytes = new Uint8Array(0);
    }
    let batch: Batch;
    try {
      batch = parseBatch(bytes);
    } catch (err) {
      if (err instanceof ProtocolError) {
        log.error("ws", "rejected batch:", err.message);
        return;
      }
      throw err;
    }
    log.info("ws", "← recv", describeBatch(batch));
    log.debug("ws", "← recv detail", describeBatchDetail(batch));
    if (batch.version !== VERSION) {
      log.warn("ws", `protocol version ${batch.version} != ${VERSION}; reloading`);
      location.reload();
      return;
    }
    // Sequence gap detection (spec/OPCODE.md §Sequence gap detection): a
    // guest → host delta batch whose sequence breaks the chain means one or more
    // batches were lost while the socket stayed open. Do not apply the gapped
    // batch (its deltas assume the lost state); request a full snapshot and
    // re-baseline on the next batch.
    if (this.isSequenceGap(batch)) {
      log.warn(
        "ws",
        `sequence gap: expected ${this.expectedSequence}, got ${batch.sequence} — requesting RESYNC`,
      );
      this.expectedSequence = null;
      this.send(encodeResync());
      return;

package dev.pathland.server;

import dev.pathland.render.html.HtmlRenderer;
import dev.pathland.server.proxy.ProxyHost;
import dev.pathland.server.proxy.ProxySession;
import dev.pathland.view.Environment;
import dev.pathland.view.EnvironmentBinding;
import dev.pathland.view.Platform;
import dev.pathland.view.ProxyConfig;
import dev.pathland.view.emit.Emitter;
import dev.pathland.view.emit.ProtocolFrame;
import dev.pathland.view.emit.FrameOpcodeSink;
import dev.pathland.view.emit.InputDispatcher;
import dev.pathland.view.emit.RenderResult;
import dev.pathland.view.signal.Signals;
import dev.pathland.view.signal.WritableSignal;
import dev.pathland.view.state.PersistentState;
import dev.pathland.view.state.StateStore;
import dev.pathland.view.transport.EnvironmentData;
import dev.pathland.view.transport.Event;
import dev.pathland.view.transport.FrameCodec;
import static dev.pathland.view.Modifiers.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * One Pathland application instance per session (1:1 with a client). Owns the session's
 * {@link PersistentState}, the retained tree, the fine-grained emitter, and the single
 * connection it sends deltas to — all transport-agnostic ({@link PathlandConnection}).
 *
 * <p>The platform environment (spec/OPCODE.md §Environment fields) seeds the app: the
 * initial route comes from its {@code ROUTE} field (a request URL on SSR; the DOM
 * client's first message over the WebSocket), delivered to the tree as the
 * {@code Platform.ACTIVE_PATH} signal. Later environment messages **enrich** the session
 * (viewport resizes, future fields) via {@link #applyEnvironment}.
 *
 * <p>State wiring is automatic: {@code State} fields in the app's views connect to the
 * store at mount. The connection is wired only <em>after</em> mount, so the mount frame
 * (already SSR'd) is never re-sent.
 */
public final class PathlandSession {

    private static final Logger LOG = LoggerFactory.getLogger(PathlandSession.class);

    /** The reserved framework path prefix (spec): host system endpoints (the
     *  WebSocket, the DOM client bundle, the asset mount) live under
     *  {@code /_pathland/**}, never colliding with app routes. */
    public static final String PATHLAND_BASE = "/_pathland";

    /** How long the SSR path waits for a proxy's origin snapshot before rendering a placeholder. */
    private static final long PROXY_SNAPSHOT_TIMEOUT_MILLIS = 2_000;

    private final PersistentState state;
    private final WritableSignal<String> activePath;
    private final String stateScope;

    private final String base;
    private final FrameOpcodeSink sink;
    private final DeltaBatcher batcher;
    private final Emitter emitter;
    private final InputDispatcher inputDispatcher;
    private final int rootId;
    private final boolean debugHtml;
    private final PathlandTelemetry telemetry;
    private final String mount;

    /** node id → proxy config for every {@code PROXY_VIEW} in the mounted tree (spec/PROXY.md). */
    private final Map<Integer, ProxyConfig> proxyViews;

    private float viewportWidth = -1f;
    private float viewportHeight = -1f;

    private volatile PathlandConnection connection;
    private volatile ProxyHost proxyHost;

    /** The outbound transport for proxy origin connections (default: the JDK WebSocket client). */
    private dev.pathland.server.proxy.ProxyTransport.Factory proxyTransportFactory =
            dev.pathland.server.proxy.JdkWebSocketTransport.factory();

    public PathlandSession(String sessionId, StateStore store, PathlandApp app, EnvironmentData env) {
        this(sessionId, store, app, env, false);
    }

    public PathlandSession(
            String sessionId,
            StateStore store,
            PathlandApp app,
            EnvironmentData env,
            boolean debugHtml) {
        this(sessionId, store, app, env, debugHtml, PATHLAND_BASE, sessionId);
    }

    public PathlandSession(
            String sessionId,
            StateStore store,
            PathlandApp app,
            EnvironmentData env,
            boolean debugHtml,
            String base,
            String stateScope) {
        this(sessionId, store, app, env, debugHtml, base, stateScope, PathlandTelemetry.NOOP, "/");
    }

    public PathlandSession(
            String sessionId,
            StateStore store,
            PathlandApp app,
            EnvironmentData env,
            boolean debugHtml,
            String base,
            String stateScope,
            PathlandTelemetry telemetry,
            String mount) {
        this.debugHtml = debugHtml;
        this.base = base;
        this.telemetry = telemetry == null ? PathlandTelemetry.NOOP : telemetry;
        this.mount = mount == null ? "/" : mount;
        this.state = new PersistentState(store, stateScope);
        this.stateScope = stateScope;
        // The active platform path is a host-provided signal (Platform.ACTIVE_PATH); the
        // app reads it, and a bound Router re-routes guard-aware on external changes.
        this.activePath = Signals.signal(env.route());

        this.sink = new FrameOpcodeSink() {
            @Override
            public void endFrame() {
                super.endFrame();
                // Only live deltas go out: the mount frame (emitted in the
                // constructor, before the session attaches) is NOT sent — the
                // client already has the whole UI from the HTML. A dead
                // connection's frames are dropped (a reconnect re-syncs).
                PathlandConnection conn = connection;
                if (conn == null || !conn.isOpen()) {
                    return;
                }
                ProtocolFrame frame = frame();
                if (!frame.opcodes().isEmpty()) {
                    batcher.append(frame);
                }
            }
        };
        this.batcher = new DeltaBatcher(this::sendBatch, this.telemetry, this.mount);
        this.emitter = new Emitter(sink, app.theme());
        // SSR full-snapshot emission: fit slots carry ALL candidates so the web
        // renderer shows every branch (CSS container queries gate the first paint —
        // issue #141). The live reconcile path still emits one selected child after
        // the first FIT_CHANGED; this stays invisible to DSL authors.
        this.emitter.snapshotEmission(true);

        // Mount wires State fields, then renders and emits the structural frame. The
        // active path is injected as a scoped environment value; any root works (with or
        // without navigation).
        RenderResult result = emitter.mount(
                app.newRoot().modifiers(environmentBinding(e -> e.key(Platform.ACTIVE_PATH).value(activePath))),
                new Environment(state));
        this.inputDispatcher = new InputDispatcher(result, activePath);
        this.rootId = result.rootId();
        this.proxyViews = result.proxyViews();
        // A structural reconcile may add/remove a PROXY_VIEW node (e.g. a SizeThatFits
        // slot dropping the candidate that held it) — reconcile the proxy sessions
        // against the live proxyViews map so a proxy lives exactly while its node is
        // in the retained tree (spec/PROXY.md §7).
        this.emitter.onStructureReconciled(this::reconcileProxies);
        applyEnvironment(env); // records viewport; the router already seeded from env.route()
    }

    /** Apply (or enrich) the platform environment after mount (viewport resizes, …). */
    public void applyEnvironment(EnvironmentData env) {
        activePath.set(env.route()); // re-route if the platform moved (guards run in the bound router)
        if (env.viewportWidth() > 0) {
            viewportWidth = env.viewportWidth();
        }
        if (env.viewportHeight() > 0) {
            viewportHeight = env.viewportHeight();
        }
    }

    /** Wire the live connection AFTER mount (the initial frame was already SSR'd). */
    public void connect(PathlandConnection connection) {
        this.connection = connection;
        reconcileProxies();
    }

    /**
     * Reconcile the proxy sessions against the live {@code proxyViews} map: open an
     * origin connection for every {@code PROXY_VIEW} node in the retained tree, and
     * close the connection of every node that left it (spec/PROXY.md §7). Driven by
     * the emitter's structural-reconcile callback, so a proxy lives exactly while its
     * node is in the tree — e.g. a {@code SizeThatFits} slot dropping the candidate
     * that held it closes the origin connection, and re-adding it opens a fresh one.
     * The origin is given this session's window scope as its {@code wid}, so the
     * origin's persisted state is per-window.
     */
    private void reconcileProxies() {
        if (proxyHost == null) {
            if (proxyViews.isEmpty()) {
                return;
            }
            proxyHost = new ProxyHost(
                    batcher::append, stateScope, viewportWidth, viewportHeight, telemetry, mount,
                    proxyTransportFactory);
        }
        proxyHost.reconcile(proxyViews);
    }

    /**
     * Set the outbound transport for proxy origin connections (spec/PROXY.md §1).
     * Defaults to the JDK WebSocket client; a framework starter may supply a native
     * client (Quarkus websockets-client, Spring {@code StandardWebSocketClient}).
     */
    public void proxyTransportFactory(dev.pathland.server.proxy.ProxyTransport.Factory factory) {
        this.proxyTransportFactory = factory;
    }

    /** Re-send the current tree as a full snapshot (META::RESYNC), flushed immediately. */
    public void resync() {
        emitter.renderFull();
        // A's own emitter does not carry the origin subtree (it is forwarded), so a
        // client resync must also refresh the proxy regions from their origins.
        ProxyHost host = proxyHost;
        if (host != null) {
            host.resyncAll();
        }
        batcher.flush();
    }

    /**
     * Send an encoded batch to the connection. On any send failure (or a closed
     * connection) the connection is dropped and best-effort closed, so the DOM
     * client reconnects and requests a {@code META::RESYNC} instead of silently
     * stalling on an "open" WebSocket that never delivers.
     */
    private void sendBatch(byte[] bytes) {
        PathlandConnection conn = connection;
        if (conn == null || !conn.isOpen()) {
            connection = null;
            return;
        }
        try {
            conn.send(bytes);
        } catch (Exception e) {
            connection = null;
            telemetry.connectionFailed(mount, e.getMessage());
            closeConnection(conn);
        }
    }

    /** Best-effort close of a failed connection (the adapters may expose a close). */
    private static void closeConnection(PathlandConnection conn) {
        if (conn instanceof AutoCloseable closeable) {
            try {
                closeable.close();
            } catch (Exception ignored) {
                // best-effort: the session already dropped the connection
            }
        }

        }
    }

    /** Route an inbound event batch (raw host → guest opcodes) into the app's bindings. */
    public void dispatch(byte[] message) {
        dispatch(FrameCodec.decodeEvents(message));
    }

    /** Route decoded events into the app's bindings (a host may pre-transform them, e.g. mount-strip NAVIGATE urls). */
    public void dispatch(Iterable<Event> events) {
        try {
            ProxyHost host = proxyHost;
            if (host == null) {
                inputDispatcher.dispatch(events);
                return;
            }
            // Events whose target is in a proxy's id range belong to the origin
            // server; everything else dispatches to the app's own bindings.
            List<Event> local = new ArrayList<>();
            for (Event event : events) {
                if (!host.forward(event)) {
                    local.add(event);
                }
            }
            if (!local.isEmpty()) {
                inputDispatcher.dispatch(local);
            }
        } catch (RuntimeException e) {
            LOG.warn("dropping event batch: {}", e.getMessage());
        }
    }

    /** Render the SSR HTML for this session's current tree (request thread). */
    public String renderHtml() {
        return renderHtml(false);
    }

    /**
     * Render the SSR HTML. {@code serviceWorker} opts the DOM client into the
     * per-window-id service worker (issue #155) by emitting
     * {@code data-pathland-service-worker} on {@code <html>}; the client registers
     * from it (and unregisters when it is absent — the kill switch).
     */
    public String renderHtml(boolean serviceWorker) {
        return renderHtml(serviceWorker, false);
    }

    /**
     * Render the SSR HTML. {@code serviceWorker} opts the DOM client into the
     * per-window-id service worker (issue #155) by emitting
     * {@code data-pathland-service-worker} on {@code <html>}; the client registers
     * from it (and unregisters when it is absent — the kill switch).
     *
     * <p>{@code ssrScoped} records that the request carried a real per-window id, so
     * this document was rendered with that window's persisted state — emitted as
     * {@code data-pathland-ssr-scoped} so the client can skip its initial
     * {@code META::RESYNC} (the live session shares the same scope).
     */
    public String renderHtml(boolean serviceWorker, boolean ssrScoped) {
        HtmlRenderer renderer = HtmlRenderer.tryInstance();
        if (renderer == null) {
            return "<!DOCTYPE html><html><body><h1>Pathland renderer unavailable</h1>"
                    + "<p>Build the Rust crate so libpathland_render_html is embedded in the "
                    + "pathland-render-html jar.</p></body></html>";
        }
        ProtocolFrame frame = ssrFrame();
        String html = debugHtml
                ? renderer.renderDebug(frame, rootId)
                : renderer.render(frame, rootId);
        // The reserved framework path prefix (spec): host system endpoints live
        // under `/{base}/**`. Carried as `data-pathland-base` so the DOM client
        // resolves its WebSocket and the bundle from the same base. Multi-app
        // hosts give each mounted app its own base (e.g. `/app2/_pathland`).
        // The bundle name is content-hashed (see PathlandAssets) so a new build
        // busts the immutable asset cache via a fresh URL.
        return html
                .replace("<html>", "<html data-pathland-base=\"" + base + "\""
                        + (serviceWorker ? " data-pathland-service-worker=\"true\"" : "")
                        + (ssrScoped ? " data-pathland-ssr-scoped=\"true\"" : "") + ">")
                .replace("</body>", "<script src=\"" + base + "/" + PathlandAssets.bundleName()
                        + "\" defer></script></body>");
    }

    /**
     * The frame the SSR document is rendered from: the session's mount frame plus,
     * for every {@code PROXY_VIEW}, the origin's remapped snapshot spliced in
     * (spec/PROXY.md §5) — one document, one render, so the renderer emits the
     * origin's fit band rules and token overrides into the same head. A proxy whose
     * origin does not answer within the timeout renders empty (a placeholder) and
     * hydrates over the live connection.
     */
    private ProtocolFrame ssrFrame() {
        ProtocolFrame frame = sink.frame();
        if (proxyViews.isEmpty()) {
            return frame;
        }
        return FrameMerger.merge(frame, proxySnapshots(PROXY_SNAPSHOT_TIMEOUT_MILLIS));
    }

    /** Start the proxies (SSR) and block for each origin's snapshot (bounded per proxy). */
    private List<ProtocolFrame> proxySnapshots(long timeoutMillis) {
        reconcileProxies();
        ProxyHost host = proxyHost;
        if (host == null) {
            return List.of();
        }
        List<ProtocolFrame> snapshots = new ArrayList<>();
        for (ProxySession session : host.sessions()) {
            try {
                ProtocolFrame snapshot = session.awaitSnapshot(timeoutMillis);
                if (snapshot != null) {
                    snapshots.add(snapshot);
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                break;
            }
        }
        return snapshots;
    }

    /** Tear down: close the persistent state, unsubscribe the emitter, stop the batcher, drop the connection. */
    public void close() {
        ProxyHost host = proxyHost;
        if (host != null) {
            host.close();
            proxyHost = null;
        }
        state.close();
        emitter.destroy();
        batcher.close();
        connection = null;
    }
}

package dev.pathland.server;

import dev.pathland.view.router.Router;
import dev.pathland.view.state.StateStore;
import dev.pathland.view.transport.EnvironmentData;
import dev.pathland.view.transport.Event;
import dev.pathland.view.transport.FrameCodec;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/**
 * The application registry: 1:1 sessions keyed by a per-connection id. Each WebSocket
 * connection owns one {@link PathlandSession} (its own retained tree + deltas); two
 * windows of the same browser never share a session. Transport-agnostic — the framework
 * starters adapt their connection type to {@link PathlandConnection}.
 *
 * <p>Session <b>identity</b> (the map key) and the <b>persisted-state scope</b> are
 * deliberately separate: the registry is keyed by a fresh per-connection {@code uiId},
 * while the {@link PersistentState} scope comes from a client-provided window id
 * ({@code wid}, carried on the WebSocket query string) so each window keeps its own
 * persisted state across reloads.
 *
 * <p>Sessions are created **lazily on the first inbound message**: the platform
 * environment ({@code META::ENVIRONMENT}, spec/OPCODE.md) arrives as the DOM client's
 * first message, and its {@code ROUTE} field seeds the router before mount — so a
 * deep-linked URL renders the right destination and the WebSocket tree stays consistent
 * with the SSR HTML. {@code open} only registers the pending connection; later
 * environment messages **enrich** the session via {@code applyEnvironment}.
 *
 * <p>All session work is serialized on a single actor thread (signals are single-threaded
 * by contract). Per-session SSR runs on the request thread against the thread-safe
 * {@link StateStore} (a throwaway {@link PathlandSession}).
 */
public final class PathlandRegistry {

    private static final Logger LOG = LoggerFactory.getLogger(PathlandRegistry.class);

    private static final int MAX_EVENT_BATCH = 1 << 16;

    private final String mountPath;
    private final PathlandApp app;
    private final StateStore store;
    private final boolean debugHtml;
    private final PathlandTelemetry telemetry;
    private final boolean serviceWorker;

    private final ExecutorService actor = Executors.newSingleThreadExecutor(r -> {
        Thread t = new Thread(r, "pathland-actor");
        t.setDaemon(true);
        return t;
    });

    private final Map<String, PathlandSession> sessions = new ConcurrentHashMap<>();
    private final Map<String, PendingSession> pending = new ConcurrentHashMap<>();

    public PathlandRegistry(PathlandApp app, StateStore store) {
        this("/", app, store, false);
    }

    public PathlandRegistry(PathlandApp app, StateStore store, boolean debugHtml) {
        this("/", app, store, debugHtml);
    }

    public PathlandRegistry(String mountPath, PathlandApp app, StateStore store, boolean debugHtml) {
        this(mountPath, app, store, debugHtml, PathlandTelemetry.NOOP);
    }

    public PathlandRegistry(
            String mountPath, PathlandApp app, StateStore store, boolean debugHtml, PathlandTelemetry telemetry) {
        this(mountPath, app, store, debugHtml, telemetry, false);
    }

    public PathlandRegistry(
            String mountPath,
            PathlandApp app,
            StateStore store,
            boolean debugHtml,
            PathlandTelemetry telemetry,
            boolean serviceWorker) {
        this.mountPath = mountPath == null || mountPath.isBlank() ? "/" : mountPath;
        this.app = app;
        this.store = store;
        this.debugHtml = debugHtml;
        this.telemetry = telemetry == null ? PathlandTelemetry.NOOP : telemetry;
        this.serviceWorker = serviceWorker;
    }

    /** Whether the SSR opts the DOM client into the per-window-id service worker (issue #155). */
    public boolean serviceWorker() {
        return serviceWorker;
    }

    /** The reserved framework URL the service worker script is served from (under this app's base). */
    public String serviceWorkerUrl() {
        return base() + "/sw.js";
    }

    /** Whether SSR HTML is rendered with per-node debug comments. */
    public boolean isDebugHtml() {
        return debugHtml;
    }

    /** The normalized subpath prefix this registry's app is mounted at ({@code "/"} for root). */
    public String mountPath() {
        return mountPath;
    }

    /** The reserved framework base this app's host endpoints live under (e.g. {@code "/app2/_pathland"}). */
    public String base() {
        return "/".equals(mountPath) ? PathlandSession.PATHLAND_BASE : mountPath + PathlandSession.PATHLAND_BASE;
    }

    /**
     * The state-store scope for a session of this app: app-qualified so two apps sharing
     * a store never collide on the same window id ({@code "mount:windowId"}; bare
     * {@code windowId} for the root mount).
     */
    public String stateScope(String windowId) {
        return "/".equals(mountPath) ? windowId : mountPath + ":" + windowId;
    }

    /**
     * Strip this app's mount prefix from a route, so the app always sees its own route
     * space ({@code /app2/home} → {@code /home}). Idempotent: routes already outside the
     * mount pass through unchanged.
     */
    public String stripRoute(String route) {
        if ("/".equals(mountPath)) {
            return route;
        }
        if (route == null || route.isBlank()) {
            return "/";
        }
        if (route.equals(mountPath)) {
            return "/";
        }
        if (route.startsWith(mountPath + "/")) {
            return route.substring(mountPath.length());
        }
        return route;
    }

    /**
     * Render the SSR HTML (request thread), seeding the router from the request path. The
     * per-window id is carried only on the WebSocket URL (kept in {@code sessionStorage},
     * never in the page URL), so the SSR request normally has no {@code windowId} and this
     * throwaway session renders <b>defaults</b>; the client's live session (scoped by the
     * WS {@code wid}) re-syncs that window's persisted state over the WebSocket after a
     * same-tab reload. A {@code windowId} is honored when present (a stale {@code wid} a
     * shared/bookmarked URL may carry).
     */
    public String renderHtml(String route, String windowId) {
        boolean scoped = windowId != null && !windowId.isBlank();
        String scope = scoped ? stateScope(windowId) : stateScope(UUID.randomUUID().toString());
        String sessionId = UUID.randomUUID().toString();
        long start = System.nanoTime();
        PathlandSession session = new PathlandSession(
                sessionId, store, app, EnvironmentData.of(stripRoute(route)),
                debugHtml, base(), scope, telemetry, mountPath);
        try {
            return session.renderHtml(serviceWorker, scoped);
        } finally {
            telemetry.ssrRendered(mountPath, System.nanoTime() - start);
            session.close();
        }
    }

    /** Render SSR defaults (no window id — a first visit without the client running yet). */
    public String renderHtml(String route) {
        return renderHtml(route, null);
    }

    /**
     * Register a connection for a session. {@code uiId} is a fresh per-connection id (the
     * session's identity — two windows never collide); {@code windowId} is the client's
     * per-window id (the persisted-state scope, mount-prefixed). The session is created on
     * its first message.
     */
    public void open(String uiId, String windowId, PathlandConnection connection) {
        actor.execute(() -> {
            PathlandSession previous = sessions.remove(uiId);
            if (previous != null) {
                previous.close();
            }
            pending.put(uiId, new PendingSession(stateScope(windowId), connection));
        });
    }

    /** Apply the platform environment: creates the session (seeded from its ROUTE field) on first contact, or enriches it after mount. */
    public void environment(String sessionId, EnvironmentData env) {
        EnvironmentData appEnv = stripRoute(env);
        actor.execute(() -> session(sessionId, appEnv).applyEnvironment(appEnv));
    }

    /** Route an inbound event batch to the owning session (NAVIGATE urls are mount-stripped first). */
    public void dispatch(String sessionId, byte[] message) {
        if (message.length > MAX_EVENT_BATCH) {
            LOG.warn("dropping oversized event batch ({} bytes)", message.length);
            return;
        }
        actor.execute(() -> {
            List<Event> events;
            try {
                events = stripNavigateUrls(FrameCodec.decodeEvents(message));
            } catch (RuntimeException e) {
                LOG.warn("dropping malformed event batch: {}", e.getMessage());
                return;
            }
            telemetry.eventBatchReceived(mountPath, events.size());
            session(sessionId, EnvironmentData.of("/")).dispatch(events);
        });
    }

    /** Handle a META::RESYNC request: re-send the session's current tree as a snapshot. */
    public void resync(String sessionId) {
        actor.execute(() -> {
            telemetry.resyncRequested(mountPath);
            session(sessionId, EnvironmentData.of("/")).resync();
        });
    }

    /** Close and remove a session (and drop any pending connection). */
    public void close(String sessionId) {
        actor.execute(() -> {
            pending.remove(sessionId);
            PathlandSession session = sessions.remove(sessionId);
            if (session != null) {
                session.close();
                telemetry.sessionClosed(mountPath);
            }
        });
    }

    /** Shut down the registry: close every session and stop the actor. */
    public void shutdown() {
        for (PathlandSession session : sessions.values()) {
            session.close();
            telemetry.sessionClosed(mountPath);
        }
        sessions.clear();
        pending.clear();
        actor.shutdown();
    }

    /** The number of live sessions for this mount (a health/metrics gauge). */
    public int activeSessions() {
        return sessions.size();
    }

    /** Create the session on first contact, wired to its pending connection. */
    private PathlandSession session(String uiId, EnvironmentData env) {
        PathlandSession session = sessions.get(uiId);
        if (session == null) {
            PendingSession pending = this.pending.remove(uiId);
            session = new PathlandSession(
                    uiId, store, app, env, debugHtml, base(),
                    pending != null ? pending.stateScope() : stateScope(uiId), telemetry, mountPath);
            if (pending != null) {
                session.connect(pending.connection());
            }
            sessions.put(uiId, session);
            telemetry.sessionOpened(mountPath);
        }
        return session;
    }

    /** Rebuild the environment with the mount prefix stripped from its route. */
    private EnvironmentData stripRoute(EnvironmentData env) {
        return new EnvironmentData(stripRoute(env.route()), env.viewportWidth(), env.viewportHeight());
    }

    /**
     * Strip the mount prefix from a NAVIGATE event's URL (browser back/forward sends the
     * real URL, e.g. {@code http://host/app2/home}): the app's router is mount-relative, so
     * it must see {@code /home}. Non-NAVIGATE events pass through unchanged; the root mount
     * is the identity.
     */
    private List<Event> stripNavigateUrls(List<Event> events) {
        if (events.stream().noneMatch(Event::isNavigate)) {
            return events;
        }
        return events.stream()
                .map(event -> event.isNavigate() && event.url() != null
                        ? Event.navigate(stripRoute(Router.pathOf(event.url())))
                        : event)
                .toList();
    }

    /** A connection awaiting its first message, with the window id's state scope. */
    private record PendingSession(String stateScope, PathlandConnection connection) {
    }
}

