  CMD_VALUE_CHANGED,
  CMD_WHEEL,
  ENV_ROUTE,
  ENV_VIEWPORT_HEIGHT,
  ENV_VIEWPORT_WIDTH,
  FLAG_HOST_TO_GUEST,
  FLAG_NAVIGATE_URL,
  HEADER_SIZE,
  MAGIC,
  OPCODE_SIZE,
  VERSION,
} from "./constants";
import { bitsFromF32 } from "./format";

function eventBatch(command: number, a: number, b: number, c: number, opcodeFlags = 0): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true); // batch flags = guest -> host
  view.setUint32(8, 0, true); // sequence (0: not a delta batch)
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, command);
  view.setUint16(pos + 2, opcodeFlags, true);
  view.setUint32(pos + 4, a, true);
  view.setUint32(pos + 8, b, true);
  view.setUint32(pos + 12, c, true);
  return out;
}

/** A META::RESYNC request (host → guest): ask the server for a full snapshot of the current tree. */
export function encodeResync(): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0x0001, true); // batch flags = HOST_TO_GUEST
  view.setUint32(8, 0, true); // sequence (0: not a delta batch)
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_META);
  view.setUint8(pos + 1, CMD_RESYNC);
  view.setUint32(pos + 4, 0, true);
  view.setUint32(pos + 8, 0, true);
  view.setUint32(pos + 12, 0, true);
  return out;
}

/** A META::PING transport-liveness heartbeat probe (guest → host, spec/OPCODE.md §Transport heartbeat). */
export function encodePing(): Uint8Array {
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0x0000, true); // batch flags = guest -> host
  view.setUint32(8, 0, true); // sequence (0: not a delta batch)
  view.setUint32(12, 1, true); // opcodeCount
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_META);
  view.setUint8(pos + 1, CMD_PING);
  view.setUint16(pos + 2, 0, true);
  view.setUint32(pos + 4, 0, true);
  view.setUint32(pos + 8, 0, true);
  view.setUint32(pos + 12, 0, true);
  return out;
}

// --- pointer ---

/** A button press: POINTER_DOWN at viewport-relative x/y (f32). */
export function encodePointerDown(target: number, x: number, y: number, flags = 0): Uint8Array {
  return eventBatch(CMD_POINTER_DOWN, target, bitsFromF32(x), bitsFromF32(y), flags);
}

/** A pointer move / hover enter-leave at viewport-relative x/y. */
export function encodePointerMove(target: number, x: number, y: number, flags: number): Uint8Array {
  return eventBatch(CMD_POINTER_MOVE, target, bitsFromF32(x), bitsFromF32(y), flags);
}

/** A button release: POINTER_UP at viewport-relative x/y. */
export function encodePointerUp(target: number, x: number, y: number, flags = 0): Uint8Array {
  return eventBatch(CMD_POINTER_UP, target, bitsFromF32(x), bitsFromF32(y), flags);
}

// --- keyboard ---

/** KEY_DOWN (A=target, B=keyCode u16 low, C=modifiers u8 low, flag KEY_REPEAT). */
export function encodeKeyDown(target: number, keyCode: number, modifiers: number, repeat = false): Uint8Array {
  return eventBatch(CMD_KEY_DOWN, target, keyCode & 0xffff, modifiers & 0xff, repeat ? 0x0002 : 0);
}

/** KEY_UP (A=target, B=keyCode u16 low, C=modifiers u8 low). */
export function encodeKeyUp(target: number, keyCode: number, modifiers: number): Uint8Array {
  return eventBatch(CMD_KEY_UP, target, keyCode & 0xffff, modifiers & 0xff);
}

// --- value / text / date ---

/** A VALUE_CHANGED EVENT with the value as f32 bits (toggle 0/1, slider, select index, stepper). */
export function encodeValueChanged(target: number, value: number): Uint8Array {
  return eventBatch(CMD_VALUE_CHANGED, target, bitsFromF32(value), 0);
}

/** A VALUE_CHANGED EVENT with a raw 32-bit payload (e.g. a packed ARGB color). */
export function encodeValueBits(target: number, bits: number): Uint8Array {
  return eventBatch(CMD_VALUE_CHANGED, target, bits >>> 0, 0);
}

// --- media ---

/** A bound media node's play state changed (B = 0/1). */
export function encodeMediaPlayStateChanged(target: number, playing: boolean): Uint8Array {
  return eventBatch(CMD_MEDIA_PLAY_STATE_CHANGED, target, playing ? 1 : 0, 0);
}

/** A bound media node's current position (B = seconds, f32). */
export function encodeMediaTimeUpdated(target: number, seconds: number): Uint8Array {
  return eventBatch(CMD_MEDIA_TIME_UPDATED, target, bitsFromF32(seconds), 0);
}

/** A bound media node reached the end of its media. */
export function encodeMediaEnded(target: number): Uint8Array {
  return eventBatch(CMD_MEDIA_ENDED, target, 0, 0);
}

/** A bound media node's volume changed (B = 0..1, f32). */
export function encodeMediaVolumeChanged(target: number, volume: number): Uint8Array {
  return eventBatch(CMD_MEDIA_VOLUME_CHANGED, target, bitsFromF32(volume), 0);
}

/** `MEDIA_DURATION_CHANGED` (0x14): the media's duration in seconds became
 *  known / changed (target = the controller node id). */
export function encodeMediaDurationChanged(target: number, seconds: number): Uint8Array {
  return eventBatch(CMD_MEDIA_DURATION_CHANGED, target, bitsFromF32(seconds), 0);
}

/** A `SIZE_THAT_FITS` slot's selected candidate changed (B = index, f32). */
export function encodeFittedChanged(target: number, index: number): Uint8Array {
  return eventBatch(CMD_FIT_CHANGED, target, bitsFromF32(index), 0);
}

/** A DATE_CHANGED EVENT (A=target, B=days, C=millis of day). */
export function encodeDateChanged(target: number, days: number, millis: number): Uint8Array {
  return eventBatch(CMD_DATE_CHANGED, target, days >>> 0, millis >>> 0);
}

/** A TEXT_CHANGED EVENT; the text rides in the batch's string section (B = relative offset). */
export function encodeTextChanged(target: number, text: string): Uint8Array {
  const bytes = new TextEncoder().encode(text);
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4 + 4 + bytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, 0, true);
  view.setUint32(12, 1, true);
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, CMD_TEXT_CHANGED);
  view.setUint32(pos + 4, target, true);
  view.setUint32(pos + 8, 0, true); // b = relative string offset (first entry)
  view.setUint32(pos + 12, 0, true);
  // string section: [stringsLen u32][entryLen u32][utf8…]
  const stringsAt = HEADER_SIZE + OPCODE_SIZE;
  view.setUint32(stringsAt, 4 + bytes.length, true);
  view.setUint32(stringsAt + 4, bytes.length, true);
  out.set(bytes, stringsAt + 8);
  return out;
}

// --- focus / editing / submit / scroll / wheel ---

/** FOCUS_CHANGED (A=target, B=focused 0/1). */
export function encodeFocusChanged(target: number, focused: boolean): Uint8Array {
  return eventBatch(CMD_FOCUS_CHANGED, target, focused ? 1 : 0, 0);
}

/** EDITING_CHANGED (A=target, B=editing 0/1). */
export function encodeEditingChanged(target: number, editing: boolean): Uint8Array {
  return eventBatch(CMD_EDITING_CHANGED, target, editing ? 1 : 0, 0);
}

/** SUBMIT (A=target). */
export function encodeSubmit(target: number): Uint8Array {
  return eventBatch(CMD_SUBMIT, target, 0, 0);
}

/** SCROLL (A=target, B=offsetX f32, C=offsetY f32). */
export function encodeScroll(target: number, offsetX: number, offsetY: number): Uint8Array {
  return eventBatch(CMD_SCROLL, target, bitsFromF32(offsetX), bitsFromF32(offsetY));
}

/** WHEEL (A=target, B=deltaX f32, C=deltaY f32). */
export function encodeWheel(target: number, deltaX: number, deltaY: number): Uint8Array {
  return eventBatch(CMD_WHEEL, target, bitsFromF32(deltaX), bitsFromF32(deltaY));
}

// --- navigation (global, not node-keyed) ---

/** NAVIGATE to a URL (browser back/forward `popstate`, a deep link); the URL rides the string section. */
export function encodeNavigate(url: string): Uint8Array {
  const bytes = new TextEncoder().encode(url);
  const out = new Uint8Array(HEADER_SIZE + OPCODE_SIZE + 4 + 4 + bytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, 0, true);
  view.setUint32(8, 0, true);
  view.setUint32(12, 1, true);
  const pos = HEADER_SIZE;
  view.setUint8(pos, CAT_EVENT);
  view.setUint8(pos + 1, CMD_NAVIGATE);
  view.setUint16(pos + 2, FLAG_NAVIGATE_URL, true);
  view.setUint32(pos + 4, 0, true); // no target — global
  view.setUint32(pos + 8, 0, true); // b = relative string offset (first entry)
  view.setUint32(pos + 12, 0, true);
  const stringsAt = HEADER_SIZE + OPCODE_SIZE;
  view.setUint32(stringsAt, 4 + bytes.length, true);
  view.setUint32(stringsAt + 4, bytes.length, true);
  out.set(bytes, stringsAt + 8);
  return out;
}

/** NAVIGATE with no URL: a native back request (the app pops its own back-stack). */
export function encodeNavigateBack(): Uint8Array {
  return eventBatch(CMD_NAVIGATE, 0, 0, 0);
}

// --- environment (host → guest; META::ENVIRONMENT field family, spec/OPCODE.md) ---

/**
 * The platform's environment: viewport + initial route, as a batch of
 * `META::ENVIRONMENT` field opcodes (the route rides the batch's string section).
 * The DOM client sends this as its **first** message on connect and re-sends it to
 * **enrich** the environment after connect (e.g. a window resize re-emits the
 * viewport fields). The SSR host synthesizes the same message from the HTTP request.
 */
export function encodeEnvironment(width: number, height: number, route: string): Uint8Array {
  const routeBytes = new TextEncoder().encode(route);
  const out = new Uint8Array(HEADER_SIZE + 3 * OPCODE_SIZE + 4 + 4 + routeBytes.length);
  const view = new DataView(out.buffer);
  view.setUint32(0, MAGIC, true);
  view.setUint16(4, VERSION, true);
  view.setUint16(6, FLAG_HOST_TO_GUEST, true); // host (renderer) -> app
  view.setUint32(8, 0, true);
  view.setUint32(12, 3, true); // VIEWPORT_WIDTH, VIEWPORT_HEIGHT, ROUTE
  let pos = HEADER_SIZE;
  const field = (id: number, b: number) => {
    view.setUint8(pos, CAT_META);
    view.setUint8(pos + 1, CMD_ENVIRONMENT);
    view.setUint16(pos + 2, 0, true);
    view.setUint32(pos + 4, id, true);
    view.setUint32(pos + 8, b, true);
    view.setUint32(pos + 12, 0, true);
    pos += OPCODE_SIZE;
  };
  field(ENV_VIEWPORT_WIDTH, bitsFromF32(width));
  field(ENV_VIEWPORT_HEIGHT, bitsFromF32(height));
  field(ENV_ROUTE, 0); // route string at relative offset 0
  const stringsAt = pos;
  view.setUint32(stringsAt, 4 + routeBytes.length, true);
  view.setUint32(stringsAt + 4, routeBytes.length, true);
  out.set(routeBytes, stringsAt + 8);
  return out;
}

//! # pathland-render-html
//!
//! A Pathland renderer that maps opcode frames onto **declarative HTML**
//! elements. Like every Pathland renderer it is a pure function of the opcode
//! stream: it retains only its own decoded output tree (a cache), never
//! application state, and emits `WHAT` the UI is — never layout rects. Native
//! browser layout does the positioning.
//!
//! This is the "server-side render" / remote-projection target (Goal #15): the
//! same opcode stream that drives a native backend drives this HTML document.
//!
//! Frames are **self-contained**: `apply(opcodes, strings)` resolves `SET_TEXT`
//! by a *relative* offset into the frame's own string section (no mirrored
//! arena), and every rendered element carries a stable `data-pathland-id` so a
//! client can hydrate it and apply later deltas in place.

use std::collections::BTreeMap;

use pathland_core::{
    Opcode, border_edges, category, component_type, parameter, property_id, size,
    tokens::TokenValue, tree, value_type,
};

mod capi;
mod css;
mod debug;
pub mod icons;
pub mod role_spec;
pub mod token_spec;

/// The `MEDIA_CONTROLLER` shell's inline style (spec/MEDIA.md). A media
/// controller owns playback but renders nothing: the container is **off-flow**
/// (`position:absolute`, 1×1, transparent) so it contributes no spacing while
/// still being *rendered* — browsers refuse to route a `<video>`'s **audio** to
/// the output when its ancestor is `display:none` (the pipeline still runs and
/// `currentTime` advances, so the failure is silent). `visibility:hidden` /
/// `display:none` are both wrong here for the same reason.
pub const MEDIA_CONTROLLER_SHELL_STYLE: &str =
    "position:absolute;width:1px;height:1px;opacity:0;overflow:hidden;pointer-events:none";

/// The renderer-owned default typography scale for a `TEXT_STYLE` code
/// (spec/MODIFIERS.md §2): `(size_px, weight_100_900)`. `None` for an unknown
/// code. Explicit `FONT_SIZE`/`FONT_WEIGHT` override these.
fn text_style_scale(code: u8) -> Option<(f32, f32)> {
    Some(match code {
        0 => (34.0, 700.0),  // LargeTitle
        1 => (28.0, 700.0),  // Title
        2 => (22.0, 700.0),  // Title2
        3 => (20.0, 600.0),  // Title3
        4 => (17.0, 600.0),  // Headline
        5 => (15.0, 400.0),  // Subheadline
        6 => (15.0, 400.0),  // Body
        7 => (14.0, 400.0),  // Callout
        8 => (13.0, 400.0),  // Footnote
        9 => (12.0, 400.0),  // Caption
        10 => (11.0, 400.0), // Caption2
        _ => return None,
    })
}

/// A generic CSS family for a `FONT_DESIGN` code (Default → the renderer's UI
/// font, i.e. no override).
fn font_design_family(code: u8) -> Option<&'static str> {
    match code {
        1 => Some("serif"),
        2 => Some("sans-serif"),
        3 => Some("ui-monospace, SFMono-Regular, Menlo, monospace"),
        _ => None,
    }
}

/// A decoded node in the retained description.
#[derive(Debug, Clone, PartialEq)]
pub struct Node {
    /// Protocol component type id (see `pathland_core::component_type`).
    pub component: u16,
    /// Text content set via `PARAMETER::SET_TEXT`, if any.
    pub text: Option<String>,
    /// Constraint/style properties (`propertyId → value`).
    pub properties: BTreeMap<u16, u32>,
    /// `STRING`-typed properties resolved at apply time (`propertyId → text`).
    pub strings: BTreeMap<u16, String>,
    /// `DESIGN_TOKEN`-typed properties (`propertyId → token path`).
    pub token_refs: BTreeMap<u16, String>,
    /// Date value from `PARAMETER::SET_DATE`: (days since epoch, millis of day).
    pub date: Option<(i32, u32)>,
    /// Child node ids in insertion order.
    pub children: Vec<u32>,
    /// A `FIT_QUERY` threshold table, decoded numerically (ascending f32s) — the
    /// candidate `minWidth`s the web renderer turns into `@container` band rules
    /// for the SSR first paint (issue #141).
    pub fit_thresholds: Vec<f32>,
}

/// Whether a `SIZE_THAT_FITS` node satisfies the **candidate-identity contract**
/// (spec/PRIMITIVES.md §SizeThatFits): a full-snapshot slot has MORE THAN ONE
/// child, exactly one ascending `FIT_QUERY` threshold per child (so child `i` ⇔
/// candidate `i`). A frame that violates this (table length ≠ child count, or a
/// non-ascending table) cannot be CSS-gated and is rendered as the threshold-0
/// fallback child only — never as ungated overlapping candidates.
fn fit_candidates_valid(node: &Node) -> bool {
    node.children.len() > 1
        && node.fit_thresholds.len() == node.children.len()
        && node.fit_thresholds.windows(2).all(|w| w[0] <= w[1])
}

/// The `@container` band rules for every multi-candidate fit slot, rendered into
/// a `<style data-pathland-fit>` element in the document head (issue #141). For
/// each distinct threshold `T_i` (ascending) the rule is **self-contained**: at
/// `width >= T_i` show candidate `i` and hide every OTHER candidate of this slot,
/// so exactly one candidate is visible at any container width — mirroring
/// `pathland_core::fit::fit_index` (equal thresholds pick the lower index, so
/// later duplicates never get a rule).
///
/// Bands use `min-width`, so at a width past several thresholds every matching
/// rule applies; all selectors are one attribute deep (equal specificity) and
/// `!important`, and the bands are emitted **ascending**, so the highest matching
/// band wins the cascade. Below the first threshold no rule matches → candidate 0
/// keeps its default `display:contents` (fallback) and candidates ≥ 1 keep
/// `display:none`.
///
/// The child at position `i` is candidate `i` (spec/PRIMITIVES.md §SizeThatFits
/// candidate-identity contract): the slot's child order equals the `FIT_QUERY`
/// order, so the band index and the child index are the same.
fn fit_band_styles(nodes: &BTreeMap<u32, Node>) -> String {
    let mut rules = String::new();
    for (id, node) in nodes {
        if node.component != component_type::SIZE_THAT_FITS || !fit_candidates_valid(node) {
            continue;
        }
        let n = node.children.len();
        let mut seen = f32::NEG_INFINITY;
        for (i, &t) in node.fit_thresholds.iter().enumerate() {
            if i == 0 {
                seen = t;
                continue; // candidate 0 is the default-visible fallback
            }
            if t <= seen {
                continue; // equal threshold → lower index already owns the band
            }
            seen = t;
            let mut band = format!("@container pf-{id} (min-width: {t}px) {{");
            for j in 0..n {
                if j == i {
                    continue; // never hide the winner
                }
                band.push_str(&format!(
                    " [data-pathland-id=\"{id}\"] > [data-pathland-fit-cand=\"{j}\"] {{ display: none !important; }}"
                ));
            }
            band.push_str(&format!(
                " [data-pathland-id=\"{id}\"] > [data-pathland-fit-cand=\"{i}\"] {{ display: contents !important; }} }} \n"
            ));
            rules.push_str(&band);
        }
    }
    rules
}

impl Node {
    fn new(component: u16) -> Self {
        Self {
            component,
            text: None,
            properties: BTreeMap::new(),
            strings: BTreeMap::new(),
            token_refs: BTreeMap::new(),
            date: None,
            children: Vec::new(),
            fit_thresholds: Vec::new(),
        }
    }

    /// The `SELECTED` checked state, decoded from its `U8` wire value.
    fn checked(&self) -> bool {
        self.properties
            .get(&property_id::SELECTED)
            .copied()
            .unwrap_or(0)
            != 0
    }

    /// The decoded `ROLE` semantic code (0 = none when absent), from its `F32`
    /// wire value.
    fn role_code(&self) -> u8 {
        self.properties
            .get(&property_id::ROLE)
            .map(|b| f32::from_bits(*b) as u8)
            .unwrap_or(0)
    }

    /// The decoded `TEXT_STYLE` typography code (None when absent), from its
    /// `F32` wire value.
    fn text_style_code(&self) -> Option<u8> {
        self.properties
            .get(&property_id::TEXT_STYLE)
            .map(|b| f32::from_bits(*b) as u8)
    }

    /// An `F32` property value, or a default when absent.
    fn f32_property(&self, prop: u16, default: f32) -> f32 {
        self.properties
            .get(&prop)
            .copied()
            .map(f32::from_bits)
            .unwrap_or(default)
    }

    /// `CONTENT_MARGINS` (F32), if present.
    fn content_margins(&self) -> Option<f32> {
        self.properties
            .get(&property_id::CONTENT_MARGINS)
            .map(|bits| f32::from_bits(*bits))
    }

    /// A raw `U32` property value (no f32 reinterpretation), or a default.
    fn u32_property(&self, prop: u16, default: u32) -> u32 {
        self.properties.get(&prop).copied().unwrap_or(default)
    }

===CAPI===
//! Flat C ABI (`pathland_html_*`) — the cross-language host surface for the
//! HTML renderer. Every function is a pure function of a self-contained PLPL
//! batch: it parses the raw bytes, renders a full document or fragment in one
//! streaming pass (no retained state), and returns a NUL-terminated C string
//! the caller owns (release with `pathland_html_free`).
//!
//! Java binds this via JNA (`com.pathland.render.html` shim); Swift/.NET bind
//! the same ABI.

use std::ffi::{CStr, CString, c_char};
use std::os::raw::c_uchar;

use pathland_core_transport::decode_frame;

use crate::HtmlRenderer;

fn render_bytes(
    batch: *const c_uchar,
    len: u32,
    root: u32,
    fragment: bool,
    debug: bool,
) -> *const c_char {
    if batch.is_null() {
        return std::ptr::null();
    }
    let bytes = unsafe { std::slice::from_raw_parts(batch, len as usize) };
    let (opcodes, strings) = match decode_frame(bytes) {
        Ok(decoded) => decoded,
        Err(_) => return std::ptr::null(),
    };
    let renderer = HtmlRenderer::new().with_debug_comments(debug);
    let html = if fragment {
        renderer.render_fragment(&opcodes, &strings, root)
    } else {
        renderer.render_document(&opcodes, &strings, root)
    };
    match CString::new(html) {
        Ok(cs) => cs.into_raw(),
        Err(_) => std::ptr::null(),
    }
}

/// Render a self-contained PLPL batch as a **full HTML document**. Returns a
/// NUL-terminated C string owned by the caller (release with `pathland_html_free`);
/// NULL when the batch is malformed.
///
/// # Safety
/// `batch` must point to `len` readable bytes; the batch is decoded
/// bounds-checked before any rendering.
#[no_mangle]
pub unsafe extern "C" fn pathland_html_render(batch: *const c_uchar, len: u32, root: u32) -> *const c_char {
    render_bytes(batch, len, root, false, false)
}

/// Render a self-contained PLPL batch as an **HTML fragment** (no `<html>`).
/// Ownership and safety as [`pathland_html_render`].
#[no_mangle]
pub unsafe extern "C" fn pathland_html_render_fragment(
    batch: *const c_uchar,
    len: u32,
    root: u32,
) -> *const c_char {
    render_bytes(batch, len, root, true, false)
}

/// Render a self-contained PLPL batch as a **full HTML document** with
/// **debug comments** on every node (a non-zero `debug` enables them — see
/// [`crate::debug`]). Ownership and safety as [`pathland_html_render`].
#[no_mangle]
pub unsafe extern "C" fn pathland_html_render_debug(
    batch: *const c_uchar,
    len: u32,
    root: u32,
    debug: u8,
) -> *const c_char {
    render_bytes(batch, len, root, false, debug != 0)
}

/// Render a self-contained PLPL batch as an **HTML fragment** with **debug
/// comments** on every node (a non-zero `debug` enables them). Ownership and
/// safety as [`pathland_html_render`].
#[no_mangle]
pub unsafe extern "C" fn pathland_html_render_fragment_debug(
    batch: *const c_uchar,
    len: u32,
    root: u32,
    debug: u8,
) -> *const c_char {
    render_bytes(batch, len, root, true, debug != 0)
}

/// Release a string returned by [`pathland_html_render`] /
/// [`pathland_html_render_fragment`]. No-op on NULL.
///
/// # Safety
/// `ptr` must be a pointer previously returned by this module (or NULL).
#[no_mangle]
pub unsafe extern "C" fn pathland_html_free(ptr: *const c_char) {
    if !ptr.is_null() {
        drop(CString::from_raw(ptr as *mut c_char));
    }
}

/// The full `<svg>` for a canonical `ICON_NAME` — the renderer-owned glyph
/// served at `/_pathland/icons/<name>.svg`. This is how every host language
/// (Java via JNA, Swift/.NET/Node/Go via this same ABI) serves the web
/// renderer's icon glyphs from ONE Rust source, instead of copying static
/// files per platform. Returns a NUL-terminated C string owned by the caller
/// (release with [`pathland_html_free`]); never NULL except when `name` is
/// NULL — an unknown/extension name yields this renderer's fallback glyph (the
/// same one SSR inlines), so a host can always answer with a glyph.
///
/// # Safety
/// `name` must be a valid NUL-terminated C string (or NULL).
#[no_mangle]
pub unsafe extern "C" fn pathland_html_icon_svg(name: *const c_char) -> *const c_char {
    if name.is_null() {
        return std::ptr::null();
    }
    let name = unsafe { CStr::from_ptr(name) }.to_string_lossy().into_owned();
    let open = crate::icons::WEB_SVG_OPEN;
    let inner = crate::icons::web_inner(&name).unwrap_or_else(crate::icons::web_fallback_svg);
    let svg = format!("{open}{inner}</svg>");
    match CString::new(svg) {
        Ok(cs) => cs.into_raw(),
        Err(_) => std::ptr::null(),
    }
}

