    }
    fn config_mut(&mut self) -> &mut Self::Config {
        &mut self.config
    }
}

impl View for Text {
    fn build_env(&self, _env: &mut Environment) -> Node {
        let mut node = plain_node(
            Component::Text {
                text: self.config.text.clone(),
            },
            Vec::new(),
            BTreeMap::new(),
        );
        node.text_binding = self.config.binding;
        node
    }
}

