import { describe, expect, it } from "vitest";
import {
  BatchWriter,
  CAT_EVENT,
  CAT_META,
  CMD_ENVIRONMENT,
  CMD_PING,
  CMD_TEXT_CHANGED,
  ENV_ROUTE,
  ENV_VIEWPORT_WIDTH,
  HEADER_SIZE,
  MAGIC,
  OPCODE_SIZE,
  VERSION,
  decodeEvents,
  decodeHostMessage,
  encodePong,
  parseBatch,
  readList,
  readString,
} from "../src/index";

describe("@pathland/protocol", () => {
  it("writes a self-contained batch with a known header and round-trips it", () => {
    const writer = new BatchWriter();
    writer.begin();
    const hello = writer.string("hello");
    writer.push(0x01, 0x01, 0, 7, 0x01, 0);
    const offset = writer.string("Ada");
    writer.push(0x02, 0x03, 0, 7, hello, 0);
    const bytes = writer.end(3);

    const view = new DataView(bytes.buffer);
    expect(view.getUint32(0, true)).toBe(MAGIC);
    expect(view.getUint16(4, true)).toBe(VERSION);
    expect(view.getUint32(8, true)).toBe(3);
    expect(view.getUint32(12, true)).toBe(2);
    expect(bytes.length).toBe(HEADER_SIZE + 2 * OPCODE_SIZE + 4 + 13);

    const batch = parseBatch(bytes);
    expect(batch.opcodes.map((op) => [op.category, op.command])).toEqual([
      [0x01, 0x01],
      [0x02, 0x03],
    ]);
    expect(readString(batch.strings, hello)).toBe("hello");
    expect(readString(batch.strings, offset)).toBe("Ada");
  });

  it("round-trips list values", () => {
    const writer = new BatchWriter();
    writer.begin();
    const offset = writer.list([1, 2.5, -3]);
    const batch = parseBatch(writer.end());
    expect(readList(batch.strings, offset)).toEqual([1, 2.5, -3]);
  });

  it("decodes TEXT_CHANGED from the string section", () => {
    const writer = new BatchWriter();
    writer.begin();
    const text = writer.string("query");
    writer.push(CAT_EVENT, CMD_TEXT_CHANGED, 0, 4, text, 0);
    const events = decodeEvents(writer.end());
    expect(events).toHaveLength(1);
    expect(events[0]).toMatchObject({ category: CAT_EVENT, command: CMD_TEXT_CHANGED, a: 4, text: "query" });
  });

  it("decodes a META::ENVIRONMENT message", () => {
    const writer = new BatchWriter();
    writer.begin();
    writer.push(CAT_META, CMD_ENVIRONMENT, 0, ENV_VIEWPORT_WIDTH, 800, 0);
    const route = writer.string("/profile");
    writer.push(CAT_META, CMD_ENVIRONMENT, 0, ENV_ROUTE, route, 0);
    const message = decodeHostMessage(writer.end());
    expect(message.type).toBe("environment");
    if (message.type === "environment") {
      expect(message.env.route).toBe("/profile");
      expect(message.env.viewportWidth).toBe(800);
    }
  });

  it("detects META::PING and encodes META::PONG", () => {
    const writer = new BatchWriter();
    writer.begin();
    writer.push(CAT_META, CMD_PING, 0, 0, 0, 0);
    expect(decodeHostMessage(writer.end()).type).toBe("ping");
    expect(decodeHostMessage(encodePong()).type).toBe("pong");
  });
});

export interface ReadonlySignal<T> {
  (): T;
  get(): T;
  readonly __pathlandSignal: true;
}

export interface WritableSignal<T> extends ReadonlySignal<T> {
  set(value: T): void;
  update(fn: (current: T) => T): void;
  readonly __pathlandWritable: true;
}

export type MaybeSignal<T> = T | ReadonlySignal<T>;
export type Cleanup = () => void;
export type EffectFn = () => void | Cleanup;
export interface EffectRef {
  destroy(): void;
}

interface ConsumerNode {
  markDirty(): void;
  addProducer(producer: ProducerNode): void;
  removeProducer(producer: ProducerNode): void;
}

interface ProducerNode {
  readonly version: number;
  readonly consumers: Set<ConsumerNode>;
}

let activeConsumer: ConsumerNode | null = null;
const effectQueue: EffectNode[] = [];
let flushing = false;

function track(producer: ProducerNode): void {
  activeConsumer?.addProducer(producer);
}

function flushEffects(): void {
  if (flushing) return;
  flushing = true;
  try {
    while (effectQueue.length > 0) {
      const effect = effectQueue.shift()!;
      if (effect.dirty && !effect.destroyed) effect.run();
    }
  } finally {
    flushing = false;
  }
}

class SignalNode<T> implements ProducerNode {
  version = 0;
  readonly consumers = new Set<ConsumerNode>();

  constructor(
    private value: T,
    private readonly equal: (a: T, b: T) => boolean,
  ) {}

  get current(): T {
    return this.value;
  }

  read(): T {
    track(this);
    return this.value;
  }

  set(next: T): void {
    if (this.equal(this.value, next)) return;
    this.value = next;
    this.version++;
    for (const consumer of [...this.consumers]) consumer.markDirty();
    flushEffects();
  }
}

class ComputedNode<T> implements ProducerNode, ConsumerNode {
  version = 0;
  readonly consumers = new Set<ConsumerNode>();
  readonly producers = new Set<ProducerNode>();
  dirty = true;

  private computing = false;
  private hasRun = false;
  private cached!: T;
  private hasError = false;
  private error: unknown;

  constructor(
    private readonly fn: () => T,
    private readonly equal: (a: T, b: T) => boolean,
  ) {}

  addProducer(producer: ProducerNode): void {
    this.producers.add(producer);
    producer.consumers.add(this);
  }

  removeProducer(producer: ProducerNode): void {
    this.producers.delete(producer);
  }

  private clearProducers(): void {
    for (const producer of this.producers) producer.consumers.delete(this);
    this.producers.clear();
  }

  markDirty(): void {
    if (this.dirty) return;
    this.dirty = true;
    for (const consumer of [...this.consumers]) consumer.markDirty();
  }

  read(): T {
    if (this.computing) throw new Error("circular signal dependency");
    if (this.dirty) this.evaluate();
    if (this.hasError) throw this.error;
    track(this);
    return this.cached;
  }

  private evaluate(): void {
    this.computing = true;
    this.dirty = false;
    this.clearProducers();
    const previous = activeConsumer;
    activeConsumer = this;
    try {
      const next = this.fn();
      if (!this.hasRun || !this.equal(this.cached, next)) {
        this.cached = next;
        this.hasRun = true;
        this.version++;
        for (const consumer of [...this.consumers]) consumer.markDirty();
      }
      this.hasError = false;
      this.error = undefined;
    } catch (error) {
      this.hasError = true;
      this.error = error;
      this.version++;
      for (const consumer of [...this.consumers]) consumer.markDirty();
    } finally {
      activeConsumer = previous;
      this.computing = false;
    }
  }
}

class EffectNode implements ConsumerNode {
  dirty = false;
  destroyed = false;
  readonly producers = new Set<ProducerNode>();
  private cleanup: Cleanup | null = null;

  constructor(private readonly fn: EffectFn) {}

  addProducer(producer: ProducerNode): void {
    this.producers.add(producer);
    producer.consumers.add(this);
  }

  removeProducer(producer: ProducerNode): void {
    this.producers.delete(producer);
  }

  private clearProducers(): void {
    for (const producer of this.producers) producer.consumers.delete(this);
    this.producers.clear();
  }

  markDirty(): void {
    if (this.destroyed) return;
    if (!this.dirty) {
      this.dirty = true;
      effectQueue.push(this);
    }
  }

  run(): void {
    if (this.destroyed) return;
    this.dirty = false;
    if (this.cleanup) {
      this.cleanup();
      this.cleanup = null;
    }
    this.clearProducers();
    const previous = activeConsumer;
    activeConsumer = this;
    try {
      const cleanup = this.fn();
      if (typeof cleanup === "function") this.cleanup = cleanup;
    } finally {
      activeConsumer = previous;
    }
  }

  destroy(): void {
    if (this.destroyed) return;
    this.destroyed = true;
    this.dirty = false;
    if (this.cleanup) {
      this.cleanup();
      this.cleanup = null;
    }
    this.clearProducers();
  }
}

function withSignalApi<T extends object>(fn: T, api: object): T {
  return Object.assign(fn, api, { __pathlandSignal: true });
}

export function signal<T>(initial: T, equal: (a: T, b: T) => boolean = Object.is): WritableSignal<T> {
  const node = new SignalNode(initial, equal);
  const callable = (() => node.read()) as unknown as WritableSignal<T>;
  return withSignalApi(callable, {
    get: () => node.read(),
    set: (value: T) => node.set(value),
    update: (fn: (current: T) => T) => node.set(fn(node.current)),
    __pathlandWritable: true,
  }) as WritableSignal<T>;
}

export function computed<T>(fn: () => T, equal: (a: T, b: T) => boolean = Object.is): ReadonlySignal<T> {
  const node = new ComputedNode(fn, equal);
  const callable = (() => node.read()) as unknown as ReadonlySignal<T>;
  return withSignalApi(callable, { get: () => node.read() }) as ReadonlySignal<T>;
}

export function constant<T>(value: T): ReadonlySignal<T> {
  const callable = (() => value) as unknown as ReadonlySignal<T>;
  return withSignalApi(callable, {
    get: () => value,
    __pathlandConstant: true,
  }) as ReadonlySignal<T>;
}

export function effect(fn: EffectFn): EffectRef {
  const node = new EffectNode(fn);
  node.run();
  return { destroy: () => node.destroy() };
}

export function untracked<T>(fn: () => T): T {
  const previous = activeConsumer;
  activeConsumer = null;
  try {
    return fn();
  } finally {
    activeConsumer = previous;
  }
}

export function isSignal(value: unknown): value is ReadonlySignal<unknown> {
  return typeof value === "function" && (value as { __pathlandSignal?: unknown }).__pathlandSignal === true;
}

export function isConstantSignal(value: unknown): boolean {
  return isSignal(value) && (value as { __pathlandConstant?: unknown }).__pathlandConstant === true;
}

import { constant, isSignal, type MaybeSignal, type ReadonlySignal } from "./signal";

export const InputSignal = {
  from<T>(value: MaybeSignal<T> | null | undefined, fallback?: T): ReadonlySignal<T> {
    if (isSignal(value)) return value as ReadonlySignal<T>;
    if (value === null || value === undefined) return constant(fallback as T);
    return constant(value);
  },
};

import { describe, expect, it } from "vitest";
import { InputSignal, computed, effect, isSignal, signal, untracked } from "../src/index";

describe("@pathland/signals", () => {
  it("is callable and writable", () => {
    const count = signal(1);
    expect(count()).toBe(1);
    count.set(2);
    expect(count.get()).toBe(2);
    count.update((value) => value + 3);
    expect(count()).toBe(5);
    expect(isSignal(count)).toBe(true);
  });

  it("memoizes computed values and suppresses equal writes", () => {
    const count = signal(1);
    let runs = 0;
    const doubled = computed(() => {
      runs++;
      return count() * 2;
    });
    expect(doubled()).toBe(2);
    expect(doubled()).toBe(2);
    expect(runs).toBe(1);
    count.set(1);
    expect(doubled()).toBe(2);
    expect(runs).toBe(1);
    count.set(2);
    expect(doubled()).toBe(4);
    expect(runs).toBe(2);
  });

  it("flushes effects synchronously and supports cleanup", () => {
    const count = signal(0);
    const seen: number[] = [];
    const cleanups: number[] = [];
    const ref = effect(() => {
      seen.push(count());
      return () => cleanups.push(count());
    });
    count.set(1);
    count.set(2);
    ref.destroy();
    count.set(3);
    expect(seen).toEqual([0, 1, 2]);
    expect(cleanups).toEqual([1, 2, 3]);
  });

  it("does not track untracked reads", () => {
    const count = signal(0);
    let runs = 0;
    effect(() => {
      runs++;
      untracked(() => count());
    });
    count.set(1);
    expect(runs).toBe(1);
  });

  it("wraps raw values and passes signals through", () => {
    const existing = signal("x");
    expect(InputSignal.from(existing)).toBe(existing);
    const fallback = InputSignal.from<string | undefined>(undefined, "offline");
    expect(fallback()).toBe("offline");
    const literal = InputSignal.from("hello");
    expect(literal()).toBe("hello");
  });

  it("detects circular computed dependencies", () => {
    let a: ReturnType<typeof computed<number>>;
    a = computed(() => a());
    expect(() => a()).toThrow(/circular/);
  });
});

