}

/** Create a retained view element. Modifiers are immutable chainable values. */
export function element(options: ElementOptions): ViewElement {
  const base: ViewElement = {
    component: options.component,
    props: options.props ?? [],
    mods: [],
    children: options.children ?? [],
    textSignal: options.textSignal,
    textBinding: options.textBinding,
    tapAction: options.tapAction,
    modifiers(...mods: ViewModifier[]): ViewElement {
      return {
        ...base,
        mods: [...base.mods, ...mods],
        modifiers: this.modifiers,
      };
    },
  };
  return base;
}

import {
  PROP_BACKGROUND_COLOR,
  PROP_BORDER_RADIUS,
  PROP_COLOR,
  PROP_FONT_SIZE,
  PROP_PADDING,
  VAL_COLOR,
  VAL_F32,
} from "@pathland/protocol";
import type { ViewModifier } from "./element";

export function padding(value: number): ViewModifier {
  return { property: PROP_PADDING, valueType: VAL_F32, value };
}

export function cornerRadius(value: number): ViewModifier {
  return { property: PROP_BORDER_RADIUS, valueType: VAL_F32, value };
}

export function fontSize(value: number): ViewModifier {
  return { property: PROP_FONT_SIZE, valueType: VAL_F32, value };
}

export function background(color: string | number): ViewModifier {
  return { property: PROP_BACKGROUND_COLOR, valueType: VAL_COLOR, value: colorBits(color) };
}

export function foregroundStyle(color: string | number): ViewModifier {
  return { property: PROP_COLOR, valueType: VAL_COLOR, value: colorBits(color) };
}

/** Pack a CSS-like color into the wire's sRGB `0xAARRGGBB`. */
export function colorBits(color: string | number): number {
  if (typeof color === "number") return color >>> 0;
  const text = color.trim();
  if (!text.startsWith("#")) throw new Error(`unsupported color "${color}"`);
  const hex = text.slice(1);
  if (hex.length === 3) {
    const r = parseInt(hex[0]! + hex[0]!, 16);
    const g = parseInt(hex[1]! + hex[1]!, 16);
    const b = parseInt(hex[2]! + hex[2]!, 16);
    return (0xff000000 | (r << 16) | (g << 8) | b) >>> 0;
  }
  if (hex.length === 6) return (0xff000000 | parseInt(hex, 16)) >>> 0;
  if (hex.length === 8) return parseInt(hex, 16) >>> 0;
  throw new Error(`unsupported color "${color}"`);
}

