  BatchWriter,
  CAT_PARAMETER,
  CAT_TREE,
  CMD_CREATE_NODE,
  CMD_INSERT_CHILD,
  CMD_SET_PROPERTY,
  CMD_SET_TEXT,
  VAL_LIST,
  VAL_STRING,
} from "@pathland/protocol";

/** Collects one self-contained PLPL frame (opcodes + frame-local strings). */
export class FrameOpcodeSink {
  private readonly writer = new BatchWriter();
  private frameHandler: ((frame: Uint8Array) => void) | null = null;

  onFrame(handler: (frame: Uint8Array) => void): void {
    this.frameHandler = handler;
  }

  beginFrame(): void {
    this.writer.begin();
  }

  endFrame(): void {
    const frame = this.writer.end(0);
    this.frameHandler?.(frame);
  }

  createNode(id: number, component: number): void {
    this.writer.push(CAT_TREE, CMD_CREATE_NODE, 0, id, component, 0);
  }

  insertChild(parent: number, child: number, index = -1): void {
    this.writer.push(CAT_TREE, 0x03, 0, parent, child, index);
  }

  deleteNode(id: number): void {
    this.writer.push(CAT_TREE, 0x02, 0, id, 0, 0);
  }

  removeChild(parent: number, child: number): void {
    this.writer.push(CAT_TREE, 0x04, 0, parent, child, 0);
  }

  setText(node: number, text: string): void {
    const offset = this.writer.string(text);
    this.writer.push(CAT_PARAMETER, CMD_SET_TEXT, 0, node, offset, 0);
  }

  setProperty(node: number, property: number, valueType: number, value: number | string | readonly number[]): void {
    const b = ((valueType << 16) | (property & 0xffff)) >>> 0;
    if (valueType === VAL_STRING) {
      const offset = this.writer.string(value as string);
      this.writer.push(CAT_PARAMETER, CMD_SET_PROPERTY, 0, node, b, offset);
    } else if (valueType === VAL_LIST) {
      const offset = this.writer.list(value as readonly number[]);
      this.writer.push(CAT_PARAMETER, CMD_SET_PROPERTY, 0, node, b, offset);
    } else {
      this.writer.push(CAT_PARAMETER, CMD_SET_PROPERTY, 0, node, b, value as number);
    }
  }
}

import {
  PROP_BINDING_ID,
  VAL_U32,
} from "@pathland/protocol";
import { effect, isConstantSignal, type ReadonlySignal, type WritableSignal } from "@pathland/signals";
import { withAppContext, type AppContext, type ViewElement } from "@pathland/view";
import { BindingSet } from "./bindings";
import type { InputDispatcher, RenderResult } from "./input";
import type { EmitterNode } from "./node";
import type { FrameOpcodeSink } from "./sink";

interface ResolvedText {
  signal: ReadonlySignal<string> | WritableSignal<string>;
  value: string;
}

export class Emitter {
  private readonly bindings = new BindingSet();
  private tree: EmitterNode | null = null;
  private nextId = 1;
  private rootId = 0;
  private mounted = false;
  private context: AppContext | null = null;

  constructor(private readonly sink: FrameOpcodeSink) {}

  mount(root: ViewElement, context: AppContext): RenderResult {
    if (this.mounted) throw new Error("Emitter already mounted");
    this.mounted = true;
    this.context = context;
    const tree = withAppContext(context, () => this.materialize(root));
    this.tree = tree;
    this.assignIds(tree);
    this.sink.beginFrame();
    this.emitNode(tree);
    this.sink.endFrame();
    this.registerBindings(tree);
    this.rootId = tree.id;
    return this.collectResult(tree);
  }

  renderFull(): void {
    if (!this.tree) throw new Error("Emitter not mounted");
    this.sink.beginFrame();
    this.emitNode(this.tree);
    this.sink.endFrame();
  }

  destroy(): void {
    this.bindings.destroy();
    this.tree = null;
  }

  get root(): number {
    return this.rootId;
  }

  private materialize(element: ViewElement): EmitterNode {
    const children = typeof element.children === "function" ? element.children() : element.children;
    return {
      id: 0,
      component: element.component,
      props: element.props,
      mods: element.mods,
      textSignal: element.textSignal,
      textBinding: element.textBinding,
      tapAction: element.tapAction,
      children: children.map((child) => this.materialize(child)),
    };
  }

  private assignIds(node: EmitterNode): void {
    node.id = this.nextId++;
    for (const child of node.children) this.assignIds(child);
  }

  private emitNode(node: EmitterNode): void {
    this.sink.createNode(node.id, node.component);
    for (const prop of node.props) {
      this.sink.setProperty(node.id, prop.property, prop.valueType, prop.value);
    }
    for (const mod of node.mods) {
      this.sink.setProperty(node.id, mod.property, mod.valueType, mod.value);
    }
    if (node.textBinding) {
      this.sink.setProperty(node.id, PROP_BINDING_ID, VAL_U32, node.id);
    }
    const resolved = this.resolveText(node);
    if (resolved) {
      node.text = resolved.value;
      if (resolved.value !== "") this.sink.setText(node.id, resolved.value);
    }
    for (const child of node.children) {
      this.emitNode(child);
      this.sink.insertChild(node.id, child.id);
    }
  }

  private resolveText(node: EmitterNode): ResolvedText | null {
    const signal = node.textBinding ?? node.textSignal;
    if (!signal) return null;
    return { signal, value: signal() };
  }

  private registerBindings(node: EmitterNode): void {
    const resolved = this.resolveText(node);
    if (resolved && !isConstantSignal(resolved.signal)) {
      const signal = resolved.signal;
      this.bindings.add(
        effect(() => {
          const value = signal();
          if (value === node.text) return;
          node.text = value;
          this.sink.beginFrame();
          this.sink.setText(node.id, value);
          this.sink.endFrame();
        }),
      );
    }
    for (const child of node.children) this.registerBindings(child);
  }

  private collectResult(tree: EmitterNode): RenderResult {
    const textInputs = new Map<number, WritableSignal<string>>();
    const valueInputs = new Map<number, WritableSignal<number>>();
    const tapActions = new Map<number, () => void>();
    const walk = (node: EmitterNode): void => {
      if (node.textBinding) textInputs.set(node.id, node.textBinding);
      if (node.tapAction) tapActions.set(node.id, node.tapAction);
      for (const child of node.children) walk(child);
    };
    walk(tree);
    return { rootId: tree.id, textInputs, valueInputs, tapActions };
  }
}

export type { InputDispatcher };

import {
  CMD_EDITING_CHANGED,
  CMD_FOCUS_CHANGED,
  CMD_NAVIGATE,
  CMD_POINTER_UP,
  CMD_TEXT_CHANGED,
  CMD_VALUE_CHANGED,
  f32FromBits,
  type EventOpcode,
} from "@pathland/protocol";
import type { WritableSignal } from "@pathland/signals";

export interface RenderResult {
  rootId: number;
  textInputs: Map<number, WritableSignal<string>>;
  valueInputs: Map<number, WritableSignal<number>>;
  tapActions: Map<number, () => void>;
}

/** Routes raw host events into the mounted tree's bindings. */
export class InputDispatcher {
  constructor(
    private readonly result: RenderResult,
    private readonly route: WritableSignal<string>,
  ) {}

  dispatch(events: readonly EventOpcode[]): void {
    for (const event of events) {
      switch (event.command) {
        case CMD_POINTER_UP:
          this.result.tapActions.get(event.a)?.();
          break;
        case CMD_TEXT_CHANGED:
          if (event.text !== undefined) this.result.textInputs.get(event.a)?.set(event.text);
          break;
        case CMD_VALUE_CHANGED:
          this.result.valueInputs.get(event.a)?.set(f32FromBits(event.b));
          break;
        case CMD_NAVIGATE:
          if (event.text !== undefined) this.route.set(event.text);
          break;
        case CMD_FOCUS_CHANGED:
        case CMD_EDITING_CHANGED:
          break;
        default:
          break;
      }
    }
  }
}

