    return (0xff000000 | (r << 16) | (g << 8) | b) >>> 0;
  }
  if (hex.length === 6) return (0xff000000 | parseInt(hex, 16)) >>> 0;
  if (hex.length === 8) return parseInt(hex, 16) >>> 0;
  throw new Error(`unsupported color "${color}"`);
