import { readFileSync } from "node:fs";
import { createServer } from "node:http";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import express from "express";
import { pathlandExpress } from "@pathland/server/express";
import { loadSsrRenderer } from "@pathland/ssr";
import { MemoryStateStore } from "@pathland/state";
import { MusicPlayerApp } from "./app";

export interface MusicPlayerServerOptions {
  wasmPath?: string;
  publicDir?: string;
  sharedAssetsDir?: string;
}

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "../../..");

export async function createMusicPlayerServer(options: MusicPlayerServerOptions = {}) {
  const wasmPath =
    options.wasmPath ?? resolve(repoRoot, "packages/ssr/wasm/pathland_render_html.wasm");
  const publicDir =
    options.publicDir ?? resolve(repoRoot, "examples/music-player/public");
  const sharedAssetsDir =
    options.sharedAssetsDir ??
    resolve(
      repoRoot,
      "lib/java/pathland-demo-views/src/main/resources/META-INF/resources/_pathland/assets",
    );

  const ssrRenderer = await loadSsrRenderer(readFileSync(wasmPath));
  const app = express();

  // The demo reuses the shared Java demo's album art/audio/lyrics assets.
  app.use("/_pathland/assets", express.static(sharedAssetsDir));
  app.use(express.static(publicDir));

  const pathland = pathlandExpress({
    app: new MusicPlayerApp(),
    store: new MemoryStateStore(),
    ssrRenderer,
    base: "/_pathland",
    assetDir: resolve(publicDir, "_pathland"),
  });
  app.use(pathland.router);

  const server = createServer(app);
  pathland.attach(server);
  return { app, server, registry: pathland.registry };
}

import { createMusicPlayerServer } from "./server";

const port = Number(process.env.PORT ?? 4318);
const { server } = await createMusicPlayerServer();
server.listen(port, "127.0.0.1", () => {
  console.log(`music-player listening on http://127.0.0.1:${port}`);
});

import { expect, test } from "@playwright/test";

test("renders the music library, selects a track, and toggles playback", async ({ page }) => {
  await page.goto("/");

  await expect(page.getByText("Library", { exact: true })).toBeVisible();
  await expect(page.getByText("Now Playing", { exact: true })).toBeVisible();
  await expect(page.getByText("Building on Solid Ground").first()).toBeVisible();
  await expect(page.locator('[data-pathland-icon="play"]')).toHaveCount(1);
  await expect(page.locator("input[type=range]")).toHaveCount(2);

  // Select the second track; the sidebar + player bar update through deltas.
  await page.getByRole("button", { name: /Pathland Crossing/ }).click();
  await expect(page.getByText("The Crossings · Native Operations")).toBeVisible();
  await expect(page.locator('[data-pathland-icon="pause"]')).toHaveCount(1);

  // Pause toggles the transport icon back.
  await page.locator('[data-pathland-icon="pause"]').click();
  await expect(page.locator('[data-pathland-icon="play"]')).toHaveCount(1);

  // The seek slider is a live range control.
  const seek = page.locator("input[type=range]").first();
  await seek.evaluate((el) => {
    const input = el as HTMLInputElement;
    input.value = "50";
    input.dispatchEvent(new Event("input", { bubbles: true }));
  });
});

